[ExtensionOf(formDataSourceStr(SalesCreateOrder, SalesTable))]
internal final class METSalesCreateOrderSalesTableDS_Extension
{
}

Method.Source:
/// <summary>
/// Performs write action on the datasource to peform insert of active record.
/// </summary>
public void write()
{
    next write();

    SalesTable salesTable = this.cursor();

    if (METSalesTable::findBySalesTable(salesTable.RecId).RecId == 0 )
    {
        METSalesTable metSalesTableLocal;
        metSalesTableLocal.initValue();
        salesTable.metPackMETSalesTable(metSalesTableLocal);
        metSalesTableLocal.SysExtensionSerializerExtensionMap::insertAfterBaseTable(salesTable);
    }
}
